/* GPU doorbell structures, functions & helpers. */
#[repr(C)]
pub struct amdgpu_doorbell {
    /* doorbell mmio */
    pub base: resource_size_t,
    pub size: resource_size_t,
    /* Number of doorbells reserved for amdgpu kernel driver */
    pub num_kernel_doorbells: u32,
    /* Kernel doorbells */
    pub kernel_doorbells: *mut amdgpu_bo,
    /* For CPU access of doorbells */
    pub cpu_addr: *mut u32,
}

#[repr(C)]
pub struct amdgpu_doorbell_index {
    pub kiq: u32, pub mec_ring0: u32, pub mec_ring1: u32, pub mec_ring2: u32,
    pub mec_ring3: u32, pub mec_ring4: u32, pub mec_ring5: u32, pub mec_ring6: u32,
    pub mec_ring7: u32, pub userqueue_start: u32, pub userqueue_end: u32,
    pub gfx_ring0: u32, pub gfx_ring1: u32, pub gfx_userqueue_start: u32,
    pub gfx_userqueue_end: u32, pub sdma_engine: [u32; 16], pub mes_ring0: u32,
    pub mes_ring1: u32, pub ih: u32,
    pub vcn_uvd_vce: amdgpu_doorbell_index_union,
    pub vpe_ring: u32, pub first_non_cp: u32, pub last_non_cp: u32,
    pub max_assignment: u32, /* Per engine SDMA doorbell size in dword */
    pub sdma_doorbell_range: u32, /* Per xcc doorbell size for KIQ/KCQ */
    pub xcc_doorbell_range: u32,
}

#[repr(C)]
pub union amdgpu_doorbell_index_union {
    pub vcn: amdgpu_doorbell_vcn,
    pub uvd_vce: amdgpu_doorbell_uvd_vce,
}
#[repr(C)] pub struct amdgpu_doorbell_vcn { pub vcn_ring0_1: u32, pub vcn_ring2_3: u32, pub vcn_ring4_5: u32, pub vcn_ring6_7: u32 }
#[repr(C)] pub struct amdgpu_doorbell_uvd_vce { pub uvd_ring0_1: u32, pub uvd_ring2_3: u32, pub uvd_ring4_5: u32, pub uvd_ring6_7: u32, pub vce_ring0_1: u32, pub vce_ring2_3: u32, pub vce_ring4_5: u32, pub vce_ring6_7: u32 }

/* C enums are represented as constant namespaces; duplicate discriminants are intentional. */
