extern "C" {
    pub fn amdgpu_mm_rdoorbell(adev: *mut amdgpu_device, index: u32) -> u32;
    pub fn amdgpu_mm_wdoorbell(adev: *mut amdgpu_device, index: u32, v: u32);
    pub fn amdgpu_mm_rdoorbell64(adev: *mut amdgpu_device, index: u32) -> u64;
    pub fn amdgpu_mm_wdoorbell64(adev: *mut amdgpu_device, index: u32, v: u64);
    pub fn amdgpu_doorbell_init(adev: *mut amdgpu_device) -> i32;
    pub fn amdgpu_doorbell_fini(adev: *mut amdgpu_device);
    pub fn amdgpu_doorbell_create_kernel_doorbells(adev: *mut amdgpu_device) -> i32;
    pub fn amdgpu_doorbell_index_on_bar(adev: *mut amdgpu_device, db_bo: *mut amdgpu_bo, doorbell_index: u32, db_size: u32) -> u32;
}

#[macro_export] macro_rules! RDOORBELL32 { ($adev:expr, $index:expr) => { unsafe { $crate::amdgpu_mm_rdoorbell($adev, $index) } }; }
#[macro_export] macro_rules! WDOORBELL32 { ($adev:expr, $index:expr, $v:expr) => { unsafe { $crate::amdgpu_mm_wdoorbell($adev, $index, $v) } }; }
#[macro_export] macro_rules! RDOORBELL64 { ($adev:expr, $index:expr) => { unsafe { $crate::amdgpu_mm_rdoorbell64($adev, $index) } }; }
#[macro_export] macro_rules! WDOORBELL64 { ($adev:expr, $index:expr, $v:expr) => { unsafe { $crate::amdgpu_mm_wdoorbell64($adev, $index, $v) } }; }

